#include <iostream>
using namespace std;

int main() {
    long long n, m, k, l;
    cin >> n >> m >> k >> l;

    if ((2 * k <= n && 2 * l <= m) ||
        (2 * l <= n && 2 * k <= m))
        cout << "First";
    else
        cout << "Second";

    return 0;
}

#include <iostream>
using namespace std;

