    long long n, m, k, l;
    cin >> n >> m >> k >> l;

    if (m * k > n * l)
        cout << "Second";
    else
        cout << "First";

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    long long n, m, k, l;
    cin >> n >> m >> k >> l;

    long long firstTurns = (m + k - 1) / k;
    long long secondTurns = (n + l - 1) / l;

    cout << (firstTurns <= secondTurns ? "First" : "Second");
    return 0;
}

